<script>(()=>{const body=document.body,modals=[...document.querySelectorAll('.store-modal')];let opener=null;const close=()=>{modals.forEach(m=>m.hidden=true);body.style.overflow='';opener?.focus();};document.querySelectorAll('[data-store-open]').forEach(button=>button.addEventListener('click',()=>{opener=button;const modal=document.getElementById('store-offer-'+button.dataset.storeOpen);if(modal){modal.hidden=false;body.style.overflow='hidden';modal.querySelector('[data-store-close]').focus();}}));document.querySelectorAll('[data-store-close]').forEach(button=>button.addEventListener('click',close));modals.forEach(modal=>modal.addEventListener('click',event=>{if(event.target===modal)close();}));document.addEventListener('keydown',event=>{if(event.key==='Escape'&&modals.some(m=>!m.hidden))close();});})();</script>
